          "criteria": [
            "down 4 cents or more",
            "down 2 to 3 cents",
            "down about 1 cent",
            "unchanged, within half a cent either way",
            "up about 1 cent",
            "up 2 to 3 cents",
            "up 4 cents or more"
          ],
          "values": [
            -5,
            -2.5,
            -1,
            0,
            1,
            2.5,
            5
          ]
        }
      },
      "answers": {
        "delta_cents": {
          "from": "move",
          "as": "mean"
        },
        "half_width_cents": {
          "from": "move",
          "as": "half_range",
          "coverage": 0.6,
          "min": 0.5
        },
        "confidence": {
          "from": "move",
          "as": "confidence"
        },
        "driver": {
          "as": "const",
          "value": "the expectation of the move distribution"
        },
        "falsifier": {
          "as": "const",
          "value": "a print outside the quoted band before five minutes are up"
        }
      }
    }
  ]
}

